import{_ as i,l as n,o as e,c as r,v as t,p as s,x as l,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"思考预算与自适应思考","description":"","frontmatter":{"title":"思考预算与自适应思考","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/thinking-budget-adaptive.md","filePath":"llm/thinking-budget-adaptive.md","lastUpdated":1789023840000}'),B={name:"llm/thinking-budget-adaptive.md"};function m(A,a,E,c,_,u){const o=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="思考预算与自适应思考" tabindex="-1">思考预算与自适应思考 <a class="header-anchor" href="#思考预算与自适应思考" aria-label="Permalink to &quot;思考预算与自适应思考&quot;">​</a></h1><div class="epigraph"><p>同一套权重，多给一些推理 token 往往更准；预算从哪来、谁来停，是测试时缩放的旋钮。</p><footer>—— OpenAI o1 / o3 的思考时间；Snell 等测试时计算；Muennighoff 等 s1 的预算强迫</footer></div><p><a href="/llm/rl-scaling-laws">上一课</a>把训练 RL 算力与金标画在一张图上。本单元改画<strong>一次推理的长度</strong>。缺口是：R1 / o1 类模型会自己长链，但产品需要上限；太短截断推理，太长烧钱。<a href="/llm/deepseek-r1">DeepSeek-R1</a> 已写行为表象。本课写预算与自适应：何时想够了。接到混合思考、过度思考。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练侧 <a href="/llm/grpo">GRPO</a> 用终局 \\(R\\)，长度涨是因为长搜索更容易撞对。推理侧若无上限，延迟与 KV 爆。预算 \\(B\\)：思维 token 的硬顶。自适应：模型或控制器在 \\(\\lt B\\) 时决定 EOS。s1 的 budget forcing 在还没停时插入「Wait」强迫续写，显示额外 token 仍能抬分。o1 产品把思考时间当用户可见档位。</p><p>自适应失败有两头：简单题也写满 \\(B\\)（过度思考，后课）；难题在预算内乱收尾（过长过滤课的截断问题在推理时再现）。</p><h3 id="预算是策略的一部分" tabindex="-1">预算是策略的一部分 <a class="header-anchor" href="#预算是策略的一部分" aria-label="Permalink to &quot;预算是策略的一部分&quot;">​</a></h3><p>训练若从不见 \\(B\\)，推理突然截断，分布外。应在 RL 中随机 \\(B\\) 或对超 \\(B\\) 塑形，使策略会收束。与训练-推理精度不匹配同类：解码约束属于 \\(\\pi_{\\mathrm{beh}}\\)。</p><p><span class="marginnote">隐藏思维 + 用户可见摘要时，预算计的是隐藏链。摘要器另占 token，不要混进 \\(B\\) 的 SLA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬顶：到达 \\(B\\) 插入收束提示或强制 boxed。自适应：用内部置信、自检头、或「答案已稳定」规则早停。训练：过长软惩罚（DAPO）+ 随机长度上限，让策略在多档 \\(B\\) 下都还能得 \\(R\\)。评测：同一题扫 \\(B\\)，画准确率–延迟帕累托，对应 Snell 的测试时计算曲线。</p>',11)),(e(),s(h,null,{default:l(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20TH%5B%22%E6%80%9D%E7%BB%B4%20token%22%5D%0A%20%20TH%20--%3E%20DEC%7B%22%E6%9C%AA%E5%88%B0%20B%20%E4%B8%94%E6%9C%AA%E7%A1%AE%E4%BF%A1%22%7D%0A%20%20DEC%20--%3E%7C%E7%BB%A7%E7%BB%AD%7C%20TH%0A%20%20DEC%20--%3E%7C%E5%81%9C%7C%20ANS%5B%22%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%22%5D%0A%20%20B%5B%22%E9%A2%84%E7%AE%97%20B%22%5D%20--%3E%20DEC%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与并行思考（后课）对照：预算是串行加长；并行是多样本。两者都花测试时 FLOPs，可互换一段。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>额外 token 提供串行工作记忆（必要性论点，见 CoT monitorability 课）。自适应要估计边际收益。模型的口头「已经想清楚」不可靠（诚实课）。更好的是：答案跨续写稳定、或校验器可中途调用（工具课）。无校验器时，早停偏冒险。</p><p><span class="marginnote">RL 若奖励只看对错、不看 \\(B\\)，自适应不会自己省 token。必须把预算写进 \\(R\\) 或多档训练。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>竞赛评测常给足长度，产品 SLA 短，必须单独报两套。用户可见档位应与训练见过的 \\(B\\) 对齐，中间档不要只在网关截断。下一课混合模式：有些请求根本不进思维块。预算只对思维模式有意义。</p><p>用户档位必须是训练见过的 B。隐藏思维与可见摘要分开计 SLA；省 token 不会从对错奖励里长出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>思考预算是测试时缩放的硬顶；自适应是早停。</li><li>训练要见过 \\(B\\)，否则推理截断分布外。</li><li>准确率–延迟曲线比单一准确率更能描述推理模型。</li><li>省 token 必须写进奖励，不会从对错 \\(R\\) 里长出来。</li><li>出处：OpenAI o1；DeepSeek-AI R1；Snell 等测试时计算；Muennighoff 等 s1。</li></ul>',9))])}const b=i(B,[["render",m]]);export{k as __pageData,b as default};
